// Apollo Client Exercise
// Mock Apollo for the sandbox:
const mockQuests = [
  { id: '1', title: 'Slay the Dragon', xpReward: 500, status: 'OPEN' },
  { id: '2', title: 'Find the Tome', xpReward: 300, status: 'OPEN' },
];

// Mock hooks simulating Apollo:
function useQuery(query, options) {
  const [data] = useState({ quests: mockQuests });
  return { data, loading: false, error: null };
}

function useMutation(mutation) {
  const [quests, setQuests] = useState(mockQuests);
  const execute = ({ variables, optimisticResponse }) => {
    if (optimisticResponse) {
      // Apply optimistic update
      setQuests(prev => prev.map(q =>
        q.id === variables.questId
          ? { ...q, ...optimisticResponse.acceptQuest }
          : q
      ));
    }
  };
  return [execute, { loading: false }];
}

import { useState } from 'react';

// TODO: QuestList component using useQuery
function QuestList() {
  const { data, loading, error } = useQuery('GET_QUESTS');

  if (loading) return <p>Loading...</p>;
  if (error) return <p>Error!</p>;

  return (
    <ul data-testid="quest-list">
      {data.quests.map(quest => (
        <li key={quest.id} data-testid={`quest-${quest.id}`}>
          {quest.title} — {quest.status}
          {/* TODO: AcceptButton with optimistic response */}
        </li>
      ))}
    </ul>
  );
}

export default function App() {
  return (
    <div data-testid="app">
      <h1>Quest Board</h1>
      <QuestList />
    </div>
  );
}
